"use client"

import type { Gallery, SessionUser } from "@/lib/types"
import { GalleryCard } from "./gallery-card"
import { Empty, EmptyContent, EmptyDescription, EmptyHeader, EmptyTitle } from "@/components/ui/empty"
import { Archive } from "lucide-react"

interface GalleryGridProps {
  galleries: Gallery[]
  session: SessionUser | null
  onOpen: (gallery: Gallery) => void
  isFavorite: (id: string) => boolean
  onToggleFavorite: (id: string) => void
}

export function GalleryGrid({ galleries, session, onOpen, isFavorite, onToggleFavorite }: GalleryGridProps) {
  if (galleries.length === 0) {
    return (
      <Empty className="py-16">
        <EmptyHeader>
          <Archive className="size-10 text-muted-foreground" />
          <EmptyTitle>ไม่พบ Gallery</EmptyTitle>
          <EmptyDescription>ลองปรับคำค้นหรือเปิด filter ใหม่</EmptyDescription>
        </EmptyHeader>
        <EmptyContent />
      </Empty>
    )
  }

  // Cards have fixed dimensions (214.93 × 295). Use flex-wrap so they keep
  // their exact size and flow naturally across screen widths.
  return (
    <div className="flex flex-wrap gap-3 md:gap-4 justify-center sm:justify-start">
      {galleries.map((g) => (
        <GalleryCard
          key={g.id}
          gallery={g}
          session={session}
          onOpen={onOpen}
          isFavorite={isFavorite(g.id)}
          onToggleFavorite={onToggleFavorite}
        />
      ))}
    </div>
  )
}
