"use client"

import { Filter, Heart, Search, ShieldCheck, X } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group"
import { Switch } from "@/components/ui/switch"
import { Separator } from "@/components/ui/separator"
import { Label } from "@/components/ui/label"
import { cn } from "@/lib/utils"
import type { Tag } from "@/lib/types"

export type SortOrder = "newest" | "oldest"

export interface Filters {
  query: string
  tags: string[] // tag names
  sort: SortOrder
  accessibleOnly: boolean
  favoritesOnly: boolean
}

interface SearchFilterProps {
  filters: Filters
  onFiltersChange: (next: Filters) => void
  tags: Tag[]
  /** Hide the "favorites only" option if not relevant in context. Defaults to true. */
  showFavoritesOption?: boolean
  /** Hide the "accessible only" option when guest. */
  showAccessibleOption?: boolean
}

export function SearchFilter({
  filters,
  onFiltersChange,
  tags,
  showFavoritesOption = true,
  showAccessibleOption = true,
}: SearchFilterProps) {
  // Count of non-default filters (sort "newest" is the default, so it does not count).
  const activeCount =
    (filters.tags.length > 0 ? 1 : 0) +
    (filters.accessibleOnly ? 1 : 0) +
    (filters.favoritesOnly ? 1 : 0) +
    (filters.sort !== "newest" ? 1 : 0)

  const update = <K extends keyof Filters>(key: K, value: Filters[K]) => {
    onFiltersChange({ ...filters, [key]: value })
  }

  const toggleTag = (name: string) => {
    const has = filters.tags.includes(name)
    update("tags", has ? filters.tags.filter((t) => t !== name) : [...filters.tags, name])
  }

  const clearAll = () => {
    onFiltersChange({
      query: filters.query, // keep search query — clearing just the filters
      tags: [],
      sort: "newest",
      accessibleOnly: false,
      favoritesOnly: false,
    })
  }

  return (
    <div className="flex items-center gap-3 mb-4">
      <div className="relative flex-1 max-w-xl">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 size-4 text-muted-foreground pointer-events-none" />
        <Input
          type="search"
          placeholder="ค้นหา gallery..."
          value={filters.query}
          onChange={(e) => update("query", e.target.value)}
          className="pl-9 rounded-full bg-secondary/60 border-secondary focus-visible:bg-background"
          aria-label="Search galleries"
        />
      </div>

      <Popover>
        <PopoverTrigger asChild>
          <Button
            type="button"
            className={cn(
              "rounded-full gap-2 font-semibold",
              activeCount > 0
                ? "bg-primary text-primary-foreground hover:bg-primary/90"
                : "bg-primary text-primary-foreground hover:bg-primary/90",
            )}
          >
            <Filter className="size-4" />
            filter
            {activeCount > 0 && (
              <span
                aria-label={`${activeCount} filter ใช้งานอยู่`}
                className="ml-1 inline-flex items-center justify-center min-w-5 h-5 px-1.5 rounded-full bg-primary-foreground text-primary text-[11px] font-bold leading-none"
              >
                {activeCount}
              </span>
            )}
          </Button>
        </PopoverTrigger>
        <PopoverContent align="end" className="w-[340px] p-0 overflow-hidden">
          {/* Header */}
          <div className="flex items-center justify-between px-4 py-3 border-b border-border bg-secondary/40">
            <h3 className="font-bold text-sm">ตัวกรอง</h3>
            {activeCount > 0 && (
              <button
                type="button"
                onClick={clearAll}
                className="inline-flex items-center gap-1 text-xs text-muted-foreground hover:text-foreground transition-colors"
              >
                <X className="size-3" />
                ล้างตัวกรอง
              </button>
            )}
          </div>

          <div className="p-4 flex flex-col gap-4">
            {/* Sort */}
            <section>
              <Label className="text-xs font-semibold text-muted-foreground uppercase tracking-wide">
                จัดเรียง
              </Label>
              <RadioGroup
                value={filters.sort}
                onValueChange={(v) => update("sort", v as SortOrder)}
                className="flex gap-3 mt-2"
              >
                <label className="flex items-center gap-2 cursor-pointer">
                  <RadioGroupItem value="newest" id="sort-newest" />
                  <span className="text-sm">ใหม่สุด</span>
                </label>
                <label className="flex items-center gap-2 cursor-pointer">
                  <RadioGroupItem value="oldest" id="sort-oldest" />
                  <span className="text-sm">เก่าสุด</span>
                </label>
              </RadioGroup>
            </section>

            <Separator />

            {/* Tags */}
            <section>
              <div className="flex items-center justify-between">
                <Label className="text-xs font-semibold text-muted-foreground uppercase tracking-wide">
                  แท็ก
                </Label>
                <span className="text-[10px] text-muted-foreground">เลือกได้หลายอัน (OR)</span>
              </div>
              <div className="flex flex-wrap gap-1.5 mt-2">
                {tags.length === 0 && (
                  <span className="text-xs text-muted-foreground">ยังไม่มีแท็ก</span>
                )}
                {tags.map((t) => {
                  const selected = filters.tags.includes(t.name)
                  return (
                    <button
                      key={t.id}
                      type="button"
                      onClick={() => toggleTag(t.name)}
                      aria-pressed={selected}
                      className={cn(
                        "px-2.5 py-1 rounded-full text-xs font-semibold border transition-colors inline-flex items-center gap-1",
                        selected
                          ? "bg-primary text-primary-foreground border-primary"
                          : "bg-background text-foreground border-border hover:border-primary/50",
                      )}
                    >
                      {t.display}
                      {/* P2: show gallery count so user knows what to expect */}
                      <span
                        className={cn(
                          "text-[10px] font-normal",
                          selected ? "opacity-80" : "text-muted-foreground",
                        )}
                      >
                        ({t.gallery_count})
                      </span>
                    </button>
                  )
                })}
              </div>
            </section>

            {(showFavoritesOption || showAccessibleOption) && <Separator />}

            {/* Switches */}
            {(showFavoritesOption || showAccessibleOption) && (
              <section className="flex flex-col gap-3">
                {showAccessibleOption && (
                  <div className="flex items-center justify-between gap-3">
                    <div className="flex items-center gap-2 min-w-0">
                      <ShieldCheck className="size-4 text-primary shrink-0" />
                      <div className="flex flex-col min-w-0">
                        <span className="text-sm font-medium">เฉพาะที่เข้าถึงได้</span>
                        <span className="text-[11px] text-muted-foreground">
                          ตาม Role ของคุณ
                        </span>
                      </div>
                    </div>
                    <Switch
                      checked={filters.accessibleOnly}
                      onCheckedChange={(v) => update("accessibleOnly", v)}
                      aria-label="เฉพาะที่เข้าถึงได้ด้วย Role ของฉัน"
                    />
                  </div>
                )}

                {showFavoritesOption && (
                  <div className="flex items-center justify-between gap-3">
                    <div className="flex items-center gap-2 min-w-0">
                      <Heart className="size-4 text-destructive shrink-0" />
                      <div className="flex flex-col min-w-0">
                        <span className="text-sm font-medium">เฉพาะรายการโปรด</span>
                        <span className="text-[11px] text-muted-foreground">
                          ที่คุณกดหัวใจไว้
                        </span>
                      </div>
                    </div>
                    <Switch
                      checked={filters.favoritesOnly}
                      onCheckedChange={(v) => update("favoritesOnly", v)}
                      aria-label="เฉพาะรายการโปรด"
                    />
                  </div>
                )}
              </section>
            )}
          </div>
        </PopoverContent>
      </Popover>
    </div>
  )
}
