"use client"

import Image from "next/image"
import { Heart, Link2, Share2, Upload } from "lucide-react"
import type { Gallery, SessionUser } from "@/lib/types"
import { canAccessGallery } from "@/lib/access"
import { timeAgo } from "@/lib/format"
import { cn } from "@/lib/utils"
import { toast } from "sonner"

interface GalleryCardProps {
  gallery: Gallery
  session: SessionUser | null
  onOpen: (gallery: Gallery) => void
  isFavorite: boolean
  onToggleFavorite: (id: string) => void
}

export function GalleryCard({ gallery, session, onOpen, isFavorite, onToggleFavorite }: GalleryCardProps) {
  const isLoggedIn = !!session
  const hasAccess = canAccessGallery(session, gallery)

  // Determine CTA state
  let state: "login" | "open" | "lock"
  if (!isLoggedIn) state = "login"
  else if (hasAccess) state = "open"
  else state = "lock"

  const handleShare = async (e: React.MouseEvent) => {
    e.stopPropagation()
    const url = typeof window !== "undefined" ? `${window.location.origin}/gallery/${gallery.id}` : ""
    try {
      await navigator.clipboard.writeText(url)
      toast.success("คัดลอกลิงก์แชร์แล้ว")
    } catch {
      toast.error("คัดลอกลิงก์ไม่สำเร็จ")
    }
  }

  const handleFavorite = (e: React.MouseEvent) => {
    e.stopPropagation()
    onToggleFavorite(gallery.id)
  }

  const handleMainAction = () => {
    if (state === "login") {
      toast.info("กรุณาเข้าสู่ระบบก่อน", {
        description: "Please log in first to collect your rewards!",
      })
      return
    }
    if (state === "lock") {
      toast.error(`ต้องมี Role ${gallery.access.min_role_name}`, {
        description: `Grab the ${gallery.access.min_role_name.replace("Bath", "B")} Role to unlock all the perks!`,
      })
      return
    }
    onOpen(gallery)
  }

  const shortRole = gallery.access.min_role_name.replace("Bath", "B")

  return (
    <article
      className={cn(
        "group relative rounded-2xl bg-card border border-border flex flex-col",
        "shadow-sm hover:shadow-md transition-shadow",
      )}
      style={{ width: "214.93px" }}
    >
      {/* Thumbnail — inset 6px รอบด้านด้วย padding บน wrapper */}
      <div className="px-[6px] pt-[6px] shrink-0">
        <div
          className="relative overflow-hidden rounded-xl bg-muted w-full cursor-pointer"
          style={{ height: "196px" }}
          onClick={handleMainAction}
        >
          <Image
            src={gallery.thumbnail || "/placeholder.svg"}
            alt={gallery.title}
            fill
            sizes="203px"
            className="object-cover transition-transform duration-300 group-hover:scale-[1.02]"
          />

          {/* Favorite heart — overlay top-right */}
          <button
            type="button"
            onClick={handleFavorite}
            aria-label={isFavorite ? "ลบออกจากรายการโปรด" : "เพิ่มเข้ารายการโปรด"}
            aria-pressed={isFavorite}
            className={cn(
              "absolute top-1.5 right-1.5 size-8 rounded-full flex items-center justify-center backdrop-blur-sm transition-all",
              "bg-background/70 hover:bg-background/90 border border-border/60",
              "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-destructive/50",
            )}
          >
            <Heart
              className={cn(
                "size-4 transition-colors",
                isFavorite ? "fill-destructive text-destructive" : "text-foreground/70",
              )}
            />
          </button>
        </div>
      </div>

      {/* Meta + CTA */}
      <div className="flex flex-col flex-1 gap-1 px-2.5 pt-2 pb-2.5">
        <h3 className="font-bold text-[13px] leading-tight text-foreground truncate">{gallery.title}</h3>

        <div className="flex items-center gap-3 text-[10px] text-muted-foreground">
          <span className="flex items-center gap-1">
            <Upload className="size-3" aria-hidden="true" />
            {timeAgo(gallery.uploaded_at)}
          </span>
          <span className="flex items-center gap-1">
            <Link2 className="size-3" aria-hidden="true" />
            {gallery.links.length} link
          </span>
        </div>

        <div className="flex items-stretch gap-1.5 mt-1.5">
          {/* Main CTA pill */}
          <button
            type="button"
            onClick={handleMainAction}
            className={cn(
              "min-w-0 flex-1 rounded-lg flex flex-col items-center justify-center leading-none py-1.5 px-1.5 transition-colors text-center",
              state === "open"
                ? "bg-primary text-primary-foreground hover:bg-primary/90"
                : "bg-destructive text-destructive-foreground hover:bg-destructive/90",
            )}
          >
            {state === "open" && (
              <>
                <span className="text-[12px] font-extrabold tracking-wide">OPEN GALLERY</span>
                <span className="text-[9px] font-medium opacity-90 mt-0.5">Click Me!</span>
              </>
            )}
            {state === "login" && (
              <>
                <span className="text-[12px] font-extrabold tracking-wide">LOGIN NOW!</span>
                <span className="text-[7px] font-medium opacity-95 mt-0.5 leading-tight">
                  Please log in first to collect your rewards!
                </span>
              </>
            )}
            {state === "lock" && (
              <>
                <span className="text-[12px] font-extrabold tracking-wide">LOCK</span>
                <span className="text-[7px] font-medium opacity-95 mt-0.5 leading-tight">
                  {`Grab the ${shortRole} Role to unlock all the perks!`}
                </span>
              </>
            )}
          </button>

          {/* Share pill */}
          <button
            type="button"
            onClick={handleShare}
            aria-label="Share gallery"
            className="shrink-0 w-9 rounded-lg bg-destructive text-destructive-foreground flex items-center justify-center hover:bg-destructive/90 transition-colors"
          >
            <Share2 className="size-4" />
          </button>
        </div>
      </div>
    </article>
  )
}
