"use client"

import { Archive, LogIn, Settings, ChevronDown, FileText } from "lucide-react"
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"
import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"
import type { SessionUser } from "@/lib/types"
import { loginAction } from "@/app/actions"
import { useTransition } from "react"
import Link from "next/link"

export type NavView = "gallery" | "note"

interface TopBarProps {
  session: SessionUser | null
  onOpenProfile: () => void
  activeNav?: NavView
  onNavChange?: (nav: NavView) => void
}

/* Role badge colours — matches gallery-detail-modal palette */
const ROLE_COLOURS: Record<string, { bg: string; text: string; dot: string }> = {
  "699Bath": { bg: "bg-rose-500/20", text: "text-rose-300", dot: "bg-rose-400" },
  "299Bath": { bg: "bg-amber-500/20", text: "text-amber-300", dot: "bg-amber-400" },
  "199Bath": { bg: "bg-blue-500/20", text: "text-blue-300", dot: "bg-blue-400" },
  "99Bath":  { bg: "bg-violet-500/20", text: "text-violet-300", dot: "bg-violet-400" },
  "69Bath":  { bg: "bg-zinc-500/20", text: "text-zinc-300", dot: "bg-zinc-400" },
}

export function TopBar({ session, onOpenProfile, activeNav = "gallery", onNavChange }: TopBarProps) {
  const [pending, start] = useTransition()

  /* Highest active role for badge — roles_cache is ordered; take last */
  const topRole = session?.active_roles?.length
    ? session.active_roles[session.active_roles.length - 1]
    : null
  const roleCfg = topRole ? (ROLE_COLOURS[topRole] ?? ROLE_COLOURS["69Bath"]) : null

  return (
    <header className="sticky top-0 z-30 bg-primary text-primary-foreground shadow-md">
      <div className="flex items-center h-16 pr-4">
        {/* SOLARA vertical brand mark */}
        <div
          aria-label="SOLARA"
          className="h-full px-3 flex flex-col items-center justify-center text-[9px] font-bold tracking-[0.2em] leading-none bg-primary/90 border-r border-primary-foreground/10"
        >
          <span>S</span>
          <span>O</span>
          <span>L</span>
          <span>A</span>
          <span>R</span>
          <span>A</span>
        </div>

        {/* Nav */}
        <nav className="flex items-center h-full">
          {/* Gallery */}
          <button
            type="button"
            onClick={() => onNavChange?.("gallery")}
            className={cn(
              "flex flex-col items-center justify-center gap-1 px-4 h-full relative transition-colors",
              activeNav === "gallery"
                ? "text-primary-foreground"
                : "text-primary-foreground/60 hover:text-primary-foreground",
            )}
          >
            <Archive className="size-5" aria-hidden="true" />
            <span className="text-xs font-medium">Gallery</span>
            <span
              className={cn(
                "absolute bottom-0 left-2 right-2 h-0.5 rounded-t-full transition-colors",
                activeNav === "gallery" ? "bg-primary-foreground" : "bg-primary-foreground/0",
              )}
            />
          </button>

          {/* Note */}
          <button
            type="button"
            onClick={() => onNavChange?.("note")}
            className={cn(
              "flex flex-col items-center justify-center gap-1 px-4 h-full relative transition-colors",
              activeNav === "note"
                ? "text-primary-foreground"
                : "text-primary-foreground/60 hover:text-primary-foreground",
            )}
          >
            <FileText className="size-5" aria-hidden="true" />
            <span className="text-xs font-medium">Note</span>
            <span
              className={cn(
                "absolute bottom-0 left-2 right-2 h-0.5 rounded-t-full transition-colors",
                activeNav === "note" ? "bg-primary-foreground" : "bg-primary-foreground/0",
              )}
            />
          </button>

          {/* Admin nav — owner only */}
          {session?.is_owner && (
            <Link
              href="/admin"
              className="flex flex-col items-center justify-center gap-1 px-4 h-full relative text-primary-foreground/70 hover:text-primary-foreground transition-colors group"
            >
              <Settings className="size-5" aria-hidden="true" />
              <span className="text-xs font-medium">Admin</span>
              <span className="absolute bottom-0 left-2 right-2 h-0.5 bg-primary-foreground/0 group-hover:bg-primary-foreground/50 rounded-t-full transition-colors" />
            </Link>
          )}
        </nav>

        <div className="flex-1" />

        {/* ── Right side ── */}
        {session ? (
          <button
            type="button"
            onClick={onOpenProfile}
            aria-label={`Open profile for ${session.discord_tag}`}
            className={cn(
              "group flex items-center gap-0 rounded-2xl overflow-hidden",
              "bg-primary-foreground/10 hover:bg-primary-foreground/18",
              "border border-primary-foreground/10 hover:border-primary-foreground/25",
              "transition-all duration-200 active:scale-[0.98]",
            )}
          >
            {/* Avatar */}
            <div className="relative pl-1.5 py-1">
              <Avatar className="size-9 ring-2 ring-primary-foreground/20 group-hover:ring-primary-foreground/40 transition-all">
                <AvatarImage
                  src={session.avatar ?? undefined}
                  alt={session.discord_tag}
                />
                <AvatarFallback className="bg-primary-foreground/20 text-primary-foreground text-sm font-bold">
                  {session.discord_tag.slice(0, 2).toUpperCase()}
                </AvatarFallback>
              </Avatar>
              {/* Online indicator */}
              <span className="absolute bottom-1 right-0 size-2.5 rounded-full bg-emerald-400 ring-2 ring-primary" />
            </div>

            {/* Name + Role */}
            <div className="flex flex-col items-start px-3 py-1.5 min-w-0">
              <span className="text-sm font-bold text-primary-foreground leading-tight truncate max-w-[130px]">
                {session.discord_tag}
              </span>
              {roleCfg && topRole ? (
                <span className={cn(
                  "inline-flex items-center gap-1 text-[10px] font-semibold px-1.5 py-0.5 rounded-full mt-0.5",
                  roleCfg.bg, roleCfg.text,
                )}>
                  <span className={cn("size-1.5 rounded-full shrink-0", roleCfg.dot)} />
                  {topRole}
                </span>
              ) : (
                <span className="text-[10px] text-primary-foreground/45 mt-0.5">ไม่มี Role</span>
              )}
            </div>

            {/* Chevron */}
            <div className="pr-3 pl-0.5">
              <ChevronDown className="size-3.5 text-primary-foreground/50 group-hover:text-primary-foreground/80 transition-colors" />
            </div>
          </button>
        ) : (
          <Button
            type="button"
            onClick={() => start(() => loginAction())}
            disabled={pending}
            className="rounded-full bg-primary-foreground text-primary hover:bg-primary-foreground/90 font-semibold"
          >
            <LogIn className="size-4" />
            {pending ? "กำลังเข้าสู่ระบบ..." : "LOG IN"}
          </Button>
        )}
      </div>
    </header>
  )
}
