"use client"

import { useMemo, useState } from "react"
import type { DiscordConfig, Gallery, SessionUser, Tag } from "@/lib/types"
import type { AnnouncementNote } from "@/lib/db"
import { TopBar, type NavView } from "./top-bar"
import { SearchFilter, type Filters } from "./search-filter"
import { GalleryGrid } from "./gallery-grid"
import { GalleryDetailModal } from "./gallery-detail-modal"
import { ProfileModal } from "./profile-modal"
import { NoteView } from "./note-view"
import { useFavorites } from "@/hooks/use-favorites"

interface GalleryViewProps {
  session: SessionUser | null
  galleries: Gallery[]
  tags: Tag[]
  discord: DiscordConfig
  uploaderName: string
  note: AnnouncementNote | null
}

const DEFAULT_FILTERS: Filters = {
  query: "",
  tags: [],
  sort: "newest",
  accessibleOnly: false,
  favoritesOnly: false,
}

export function GalleryView({ session, galleries, tags, discord, uploaderName, note }: GalleryViewProps) {
  const [filters, setFilters] = useState<Filters>(DEFAULT_FILTERS)
  const [profileOpen, setProfileOpen] = useState(false)
  const [activeGallery, setActiveGallery] = useState<Gallery | null>(null)
  const [activeNav, setActiveNav] = useState<NavView>("gallery")

  const { favorites, isFav, toggle } = useFavorites(session)

  const filtered = useMemo(() => {
    const q = filters.query.trim().toLowerCase()
    const favSet = new Set(favorites)

    // Map tag id <-> name so the UI can pass either; store uses tag ids on galleries.
    const tagIdByName = new Map(tags.map((t) => [t.name, t.id]))
    const selectedTagIds = filters.tags
      .map((nameOrId) => tagIdByName.get(nameOrId) ?? nameOrId)
      .filter(Boolean)

    const base = galleries.filter((g) => {
      if (q && !g.title.toLowerCase().includes(q) && !g.description.toLowerCase().includes(q)) {
        return false
      }
      if (filters.accessibleOnly && session && session.max_hierarchy_level < g.access.min_hierarchy_level) {
        return false
      }
      if (filters.accessibleOnly && !session) {
        return false
      }
      if (filters.favoritesOnly && !favSet.has(g.id)) {
        return false
      }
      // OR semantics for tags: at least one selected tag must be on the gallery.
      if (selectedTagIds.length > 0 && !selectedTagIds.some((id) => g.tags.includes(id))) {
        return false
      }
      return true
    })

    // Sort — pinned always first, then by date.
    const sorted = [...base].sort((a, b) => {
      if (a.is_pinned !== b.is_pinned) return a.is_pinned ? -1 : 1
      const ta = new Date(a.uploaded_at).getTime()
      const tb = new Date(b.uploaded_at).getTime()
      return filters.sort === "newest" ? tb - ta : ta - tb
    })

    return sorted
  }, [galleries, filters, favorites, tags, session])

  return (
    <div className="min-h-screen bg-background">
      <TopBar
        session={session}
        onOpenProfile={() => setProfileOpen(true)}
        activeNav={activeNav}
        onNavChange={setActiveNav}
      />

      <main className="max-w-[1600px] mx-auto px-4 md:px-6 py-5">
        {activeNav === "gallery" ? (
          <>
            <SearchFilter
              filters={filters}
              onFiltersChange={setFilters}
              tags={tags}
              showFavoritesOption={true}
              showAccessibleOption={!!session}
            />

            <GalleryGrid
              galleries={filtered}
              session={session}
              onOpen={(g) => setActiveGallery(g)}
              isFavorite={isFav}
              onToggleFavorite={toggle}
            />
          </>
        ) : (
          <NoteView note={note} />
        )}
      </main>

      <GalleryDetailModal
        open={!!activeGallery}
        onOpenChange={(open) => !open && setActiveGallery(null)}
        gallery={activeGallery}
        session={session}
        tags={tags}
        uploaderName={uploaderName}
      />

      {session && (
        <ProfileModal
          open={profileOpen}
          onOpenChange={setProfileOpen}
          session={session}
          discord={discord}
        />
      )}
    </div>
  )
}
